import type { ExcalidrawImperativeAPI } from './excal';

/**
 * Hidratación de imágenes para poder EXPORTAR.
 *
 * Las escenas guardan la imagen como URL remota en `files[id].dataURL`
 * (Excalidraw hace `image.src = <ese campo>`, así que una URL funciona y la
 * escena pesa como un `editorConfig`, no cientos de KB en base64).
 *
 * EL PROBLEMA NO ES LA URL, ES CÓMO SE PIDE. Excalidraw carga con `new Image()`
 * y **no pone `crossOrigin` en ninguna parte** (comprobado sobre su `dist`: cero
 * ocurrencias). Sin ese atributo el navegador pide en modo *no-cors*, y entonces
 * marca el canvas como contaminado AUNQUE el servidor mande
 * `Access-Control-Allow-Origin` — esa cabecera solo se mira si la petición se
 * hizo en modo CORS. Resultado: la imagen se VE pero `toBlob()`/`toDataURL()`
 * mueren con `SecurityError`, o sea que no hay ni miniaturas ni export.
 *
 * La salida es traer los bytes por nuestra cuenta y darle a Excalidraw una URL
 * que NO contamine.
 *
 * IMPORTANTE — por qué se devuelve un mapa nuevo en vez de mutar la escena:
 * `api.addFiles()` delega en `addMissingFiles()`, que hace `continue` con todo
 * id que ya exista. Intentar reemplazar un fichero por esa vía es un NO-OP
 * silencioso: la escena se queda con la URL remota y el export sigue muriendo
 * con SecurityError. Los exportadores de Excalidraw (`exportToBlob`,
 * `exportToSvg`) reciben `files` explícitamente y son puros, así que aceptan
 * este mapa sin que la escena viva se entere.
 *
 * Que el mapa sea paralelo es además lo que hace seguro usar `blob:` aquí: un
 * `blob:` guardado en una escena la deja en blanco al reabrirla (ya pasó), pero
 * este mapa NUNCA se guarda.
 */

export type MediaFetcher = (url: string) => Promise<Blob>;

/** Forma mínima de una entrada del mapa de ficheros de Excalidraw. */
interface FileEntry {
  id: string;
  dataURL: string;
  mimeType: string;
}

export interface HydratedFiles {
  /** Mapa listo para `ExportOptions.files`. */
  files: Record<string, FileEntry>;
  /** Cuántas imágenes se inlinearon. */
  hydrated: number;
  /** URLs que no se pudieron traer. Se quedan como estaban ⇒ contaminarían. */
  failed: string[];
}

export interface HydrateOptions {
  /**
   * Qué URL se le da a Excalidraw:
   *
   *   · `'blob'` (por defecto) — `URL.createObjectURL(blob)`. Es same-origin, no
   *     contamina, y NO hay que codificar nada: los bytes se quedan fuera del
   *     heap de JS. Vale para todo lo que acabe en un canvas (PNG y miniaturas).
   *   · `'dataurl'` — base64. Solo hace falta para `exportToSvg`, porque ahí los
   *     bytes viajan DENTRO del SVG y un `blob:` no sobreviviría al fichero.
   *
   * El base64 cuesta: infla un 33% y construye una cadena enorme a trozos en el
   * hilo principal. Por eso dejó de ser el modo por defecto.
   */
  output?: 'blob' | 'dataurl';
  /** Fuerza el `fetcher` inyectado y salta el intento directo. Para tests. */
  preferProxy?: boolean;
}

/**
 * Blob → dataURL sin `FileReader`: así funciona igual en el navegador y en los
 * tests de node. Se codifica por trozos porque `String.fromCharCode(...bytes)`
 * con una imagen entera revienta la pila de llamadas.
 */
async function blobToDataUrl(blob: Blob, fallbackMime: string): Promise<string> {
  const bytes = new Uint8Array(await blob.arrayBuffer());
  const CHUNK = 0x8000;
  let binary = '';
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return `data:${blob.type || fallbackMime};base64,${btoa(binary)}`;
}

/** Un dataURL ya está inlineado; cualquier otra cosa hay que traerla. */
function needsHydration(value: unknown): value is string {
  return typeof value === 'string' && !value.startsWith('data:') && !value.startsWith('blob:');
}

// ─── Fetch directo cuando el host ya expone CORS ─────────────────────────────

/**
 * Orígenes que YA fallaron en modo CORS, para no volver a intentarlo.
 *
 * Casi todos nuestros hosts mandan `Access-Control-Allow-Origin` (medido:
 * light-media, el bucket plan-images y el backend heredado sí; el bucket de
 * logos no). Donde lo mandan, el navegador puede bajarse los bytes él solo y nos
 * ahorramos un salto por imagen contra el proxy del worker. Donde no, se cae al
 * `fetcher` inyectado — y se apunta el origen para no gastar una petición
 * condenada en cada imagen.
 */
const NO_CORS_ORIGINS = new Set<string>();

function originOf(url: string): string | null {
  try {
    return new URL(url).origin;
  } catch {
    return null;
  }
}

/**
 * Trae los bytes. Intenta CORS directo y, si el origen no lo permite, delega en
 * el `fetcher` del host (el proxy). Este módulo sigue sin saber nada de rutas ni
 * de autenticación: eso vive todo en el `fetcher`.
 */
async function fetchBytes(url: string, fetcher: MediaFetcher, preferProxy: boolean): Promise<Blob> {
  const origin = originOf(url);
  if (preferProxy || origin === null || NO_CORS_ORIGINS.has(origin)) {
    return fetcher(url);
  }
  try {
    const res = await fetch(url, { mode: 'cors', credentials: 'omit' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.blob();
  } catch {
    // Sin CORS (o caído): se recuerda el origen y se tira por el proxy. Si el
    // fallo era pasajero, el peaje es usar el proxy el resto de la sesión.
    NO_CORS_ORIGINS.add(origin);
    return fetcher(url);
  }
}

// ─── Caché de bytes ──────────────────────────────────────────────────────────

/**
 * Caché de lo ya hidratado, por URL y modo de salida.
 *
 * Sin esto, hidratar era O(imágenes) de red y de codificación en CADA llamada, y
 * las llamadas no son raras: `useCanvas2LivePreview` rehace la captura cada 10 s
 * en cuanto la huella de la escena cambia, o sea tras CUALQUIER edición. Mover
 * un elemento volvía a descargar la escena entera. Es la causa de que el lienzo
 * se atascara con fotos grandes.
 *
 * Cachear por URL es seguro porque la URL identifica los bytes: MediaMonster
 * sirve por `fileId` inmutable, las fuentes llevan el hash del contenido en el
 * nombre y las miniaturas de diseño arrastran un `?v=`. Si cambia el contenido,
 * cambia la URL y aquí es otra entrada.
 *
 * Los fallos NO se cachean a propósito: un 403 puede ser una allowlist que aún
 * no se ha desplegado o una caída pasajera, y dejarlos fijados obligaría a
 * recargar la página para recuperarse.
 */
interface CacheEntry {
  /** Lo que se le da a Excalidraw: un `blob:` o un `data:`. */
  url: string;
  mimeType: string;
  bytes: number;
  /** Los `blob:` hay que revocarlos al expulsarlos; los `data:` no. */
  revocable: boolean;
}

const BYTES_CACHE = new Map<string, CacheEntry>();

/**
 * Tope de la caché, EN BYTES y no en número de entradas.
 *
 * Contar entradas no sirve aquí: una foto de catálogo ronda 1 MB y un icono unos
 * pocos KB, así que un tope de "N imágenes" significa cosas mil veces distintas
 * según la escena. Con un presupuesto de memoria el comportamiento es predecible
 * venga lo que venga.
 */
const CACHE_MAX_BYTES = 32 * 1024 * 1024;
let cacheBytes = 0;

/**
 * Margen antes de revocar un `blob:` expulsado: puede haber un export a medias
 * usándolo todavía, y revocarlo en caliente le dejaría el hueco en blanco.
 */
const REVOKE_DELAY_MS = 5_000;

function releaseEntry(entry: CacheEntry): void {
  if (!entry.revocable) return;
  setTimeout(() => URL.revokeObjectURL(entry.url), REVOKE_DELAY_MS);
}

const cacheKey = (url: string, output: 'blob' | 'dataurl') => `${output}�${url}`;

function cacheGet(key: string): CacheEntry | undefined {
  const hit = BYTES_CACHE.get(key);
  if (!hit) return undefined;
  // Reinserta para que el orden del Map haga de LRU: lo recién usado va al final
  // y la expulsión se lleva siempre lo más viejo.
  BYTES_CACHE.delete(key);
  BYTES_CACHE.set(key, hit);
  return hit;
}

function cacheSet(key: string, entry: CacheEntry): void {
  // Una sola imagen más grande que todo el presupuesto no se cachea: guardarla
  // vaciaría la caché entera para nada.
  if (entry.bytes > CACHE_MAX_BYTES) return;

  const previo = BYTES_CACHE.get(key);
  if (previo) {
    cacheBytes -= previo.bytes;
    releaseEntry(previo);
  }
  BYTES_CACHE.set(key, entry);
  cacheBytes += entry.bytes;

  while (cacheBytes > CACHE_MAX_BYTES) {
    const oldest = BYTES_CACHE.keys().next().value;
    if (oldest === undefined) break;
    const victima = BYTES_CACHE.get(oldest);
    BYTES_CACHE.delete(oldest);
    if (victima) {
      cacheBytes -= victima.bytes;
      releaseEntry(victima);
    }
  }
}

/** Vacía la caché y revoca los `blob:` vivos. Para los tests y para un "recargar imágenes". */
export function clearHydrationCache(): void {
  for (const entry of BYTES_CACHE.values()) releaseEntry(entry);
  BYTES_CACHE.clear();
  cacheBytes = 0;
  NO_CORS_ORIGINS.clear();
}

// ─── Hidratación ─────────────────────────────────────────────────────────────

/**
 * Construye un mapa de ficheros con las URLs remotas sustituidas por otras que
 * no contaminan el canvas. No toca la escena. Las que fallen se dejan tal cual y
 * se listan en `failed`, para que quien llame decida si avisa o aborta —
 * exportar con una de ellas dentro volverá a contaminar el canvas.
 */
export async function buildHydratedFiles(
  api: ExcalidrawImperativeAPI,
  fetcher: MediaFetcher,
  { output = 'blob', preferProxy = false }: HydrateOptions = {},
): Promise<HydratedFiles> {
  const source = (api.getFiles() ?? {}) as Record<string, FileEntry>;
  const files: Record<string, FileEntry> = { ...source };
  const failed: string[] = [];
  let hydrated = 0;

  const pending = Object.values(source).filter((f) => needsHydration(f?.dataURL));
  if (pending.length === 0) return { files, hydrated, failed };

  await Promise.all(
    pending.map(async (file) => {
      const remota = file.dataURL;
      const key = cacheKey(remota, output);

      const cached = cacheGet(key);
      if (cached) {
        files[file.id] = { ...file, dataURL: cached.url, mimeType: cached.mimeType };
        hydrated += 1;
        return;
      }

      try {
        const blob = await fetchBytes(remota, fetcher, preferProxy);
        const mimeType = blob.type || file.mimeType;
        const entry: CacheEntry =
          output === 'blob'
            ? { url: URL.createObjectURL(blob), mimeType, bytes: blob.size, revocable: true }
            : await (async () => {
                const dataURL = await blobToDataUrl(blob, file.mimeType);
                return { url: dataURL, mimeType, bytes: dataURL.length, revocable: false };
              })();

        cacheSet(key, entry);
        files[file.id] = { ...file, dataURL: entry.url, mimeType: entry.mimeType };
        hydrated += 1;
      } catch {
        failed.push(remota);
      }
    }),
  );

  return { files, hydrated, failed };
}
